    /**
     * Inserts or updates the given client bar codes in batches of up to 100 using a JDBC
     * prepared statement. Failures on individual records or the batch are logged and do not
     * abort the operation.
     *
     * @param clientBarCodeDTOS the client bar codes to upsert
     */
    public void upsertClientBarCodeInBatch(Set<ClientBarCodeDTO> clientBarCodeDTOS) {
        log.info("upsertBarCodeInBatch");
        try (Connection connection = dataSource.getConnection()) {
            PreparedStatement preparedStatementUpdate = connection.prepareStatement(clientBarCodeQueryRepository.getQueryForUpsertClientBarCode());
            int batchCounter = 0;
            int maxBatchLimit = 100;
            for (ClientBarCodeDTO clientBarCodeDTO : clientBarCodeDTOS) {
                try {
                    preparedStatementUpdate.setString(1, clientBarCodeDTO.getId());
                    preparedStatementUpdate.setString(2, clientBarCodeDTO.getAddedAt());
                    preparedStatementUpdate.setString(3, clientBarCodeDTO.getAddedBy());
                    preparedStatementUpdate.setString(4, clientBarCodeDTO.getClientBarCodeId());
                    preparedStatementUpdate.setString(5, clientBarCodeDTO.getDeviceId());
                    preparedStatementUpdate.setString(6, clientBarCodeDTO.getLocationId());
                    if (clientBarCodeDTO.getUpdatedTime() == null) {
                        preparedStatementUpdate.setNull(7, java.sql.Types.NUMERIC);
                    } else {
                        preparedStatementUpdate.setBigDecimal(7, new java.math.BigDecimal(clientBarCodeDTO.getUpdatedTime()));
                    }
                    preparedStatementUpdate.setString(8, clientBarCodeDTO.getUpdatedBy());
                    preparedStatementUpdate.setString(9, clientBarCodeDTO.getVdmsId());
                    preparedStatementUpdate.setString(10, clientBarCodeDTO.getBatchId());
                    preparedStatementUpdate.addBatch();
                    batchCounter++;
                    if (batchCounter == maxBatchLimit) {
                        preparedStatementUpdate.executeBatch();
                        log.info("added 100 barcode in a batch");
                        preparedStatementUpdate.clearBatch();
                        batchCounter = 0;
                    }
                } catch (Exception e) {
                    log.error("Exception in batch update of barcode", e);
                }
            }
            if (batchCounter > 0) {
                preparedStatementUpdate.executeBatch();
                log.info("Excecuted batch update of: {} barcode ", batchCounter);
            }
            preparedStatementUpdate.close();
        } catch (Exception e) {
            log.error("Exception in batch update of barcode", e);
        }
    }

